const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function motionCode(entry,settings,text,accent){const cssName=s=>s.replace(/[A-Z]/g,c=>'-'+c.toLowerCase());const blocks=entry.frames.map((f,i)=>`${Math.round((f.offset??i/(entry.frames.length-1))*100)}% { ${Object.entries(f).filter(([k])=>k!=='offset').map(([k,v])=>`${k==='easing'?'animation-timing-function':cssName(k)}: ${v};`).join(' ')} }`).join('\n  ');const visual=entry.visual;const base={orb:'width: 85px; height: 85px; border-radius: 50%;',word:'display: inline-block; font: 900 64px/1.2 Arial, sans-serif; letter-spacing: -4px;',card:'width: 85px; height: 85px; border-radius: 12px;',ring:'width: 92px; height: 92px; border-radius: 50%; border: 15px solid currentColor; border-top-color: transparent;',dots:'display:flex; gap:7px;',bars:'display:flex; gap:7px; align-items:center; height:90px;',path:'width:88px; height:64px; border:9px solid currentColor; border-radius:50% 50% 15% 50%;'}[visual];const solid=['orb','card'].includes(visual);let childCSS='';if(visual==='dots')childCSS='.demo i { display:block; width:18px; height:18px; border-radius:50%; background:currentColor; }';if(visual==='bars')childCSS='.demo i { display:block; width:13px; height:70%; background:currentColor; border-radius:20px; }\n.demo i:nth-child(2), .demo i:nth-child(4) { height:100%; }';return `<div class="demo">${visual==='word'?esc(text):['bars','dots'].includes(visual)?'<i></i>'.repeat(5):''}</div>\n\n<style>\n.demo {\n  ${base}\n  color: ${accent};${solid?`\n  background: ${accent};`:''}\n  animation: ${entry.id} ${settings.duration}ms ${settings.easing} ${settings.iterations===Infinity?'infinite':'1'} both;\n}\n${childCSS}\n@keyframes ${entry.id} {\n  ${blocks}\n}\n@media (prefers-reduced-motion: reduce) {\n  .demo { animation: none; }\n}\n</style>`}
